import{_ as t,a0 as l,w as c,s as d,I as o,x as s,a1 as a,A as i,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Linux DNS 查詢剖析（第二部分） | LCTT x X-CMD","titleTemplate":false,"description":"Linux DNS 查詢剖析（第二部分） | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux DNS 查詢剖析（第二部分） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux DNS 查詢剖析（第二部分） | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180618 Anatomy of a Linux DNS Lookup - Part II","title":"Linux DNS 查詢剖析（第二部分）","tag":"201808","desc":""},"relativePath":"201808/20180618 Anatomy of a Linux DNS Lookup - Part II.md","filePath":"[post].md"}'),r={name:"201808/20180618 Anatomy of a Linux DNS Lookup - Part II.md"};function h(u,e,f,g,k,m){const n=l("Link");return c(),d("div",null,[e[19]||(e[19]=o("h1",{id:"linux-dns-查詢剖析-第二部分",tabindex:"-1"},[s("Linux DNS 查詢剖析（第二部分） "),o("a",{class:"header-anchor",href:"#linux-dns-查詢剖析-第二部分","aria-label":"Permalink to “Linux DNS 查詢剖析（第二部分）”"},"​")],-1)),o("p",null,[e[1]||(e[1]=s("在 ",-1)),a(n,{href:"https://linux.cn/article-9943-1.html"},{default:i(()=>[...e[0]||(e[0]=[s("Linux DNS 查詢剖析 - 第一部分",-1)])]),_:1}),e[2]||(e[2]=s(" 中，我介紹了：",-1))]),e[20]||(e[20]=p("<ul><li><code>nsswitch</code></li><li><code>/etc/hosts</code></li><li><code>/etc/resolv.conf</code></li><li><code>ping</code> 與 <code>host</code> 查詢方式對比</li></ul><p>並且發現大多數程序選擇要查詢的 DNS 服務器時會參考 <code>/etc/resolv.conf</code> 配置文件。</p><p>這種方式在 Linux 上比較普遍[^1]。雖然我使用了特定的發行版 Ubuntu，但背後的原理與 Debian 甚至是那些基於 CentOS 的發行版有相通的地方；當然，與更低或更高的 Ubuntu 版本相比，差異還是存在的。</p>",3)),o("p",null,[e[4]||(e[4]=s("[^1]: 事實上，這是相對於 POSIX 標準的，故不限於 Linux （我從上一篇文章的一條極好的",-1)),a(n,{href:"https://zwischenzugs.com/2018/06/08/anatomy-of-a-linux-dns-lookup-part-i/#comment-2312"},{default:i(()=>[...e[3]||(e[3]=[s("回覆",-1)])]),_:1}),e[5]||(e[5]=s("中瞭解到這一點）",-1))]),e[21]||(e[21]=p(`<p>也就是説，接下來，你主機上的行為很可能與我描述的不一致。</p><p>在第二部分中，我將介紹 <code>resolv.conf</code> 的更新機制、<code>systemctl restart networking</code> 命令的運行機制 ，以及 <code>dhclient</code> 是如何參與其中。</p><h3 id="_1-手動更新-etc-resolv-conf" tabindex="-1">1) 手動更新 /etc/resolv.conf <a class="header-anchor" href="#_1-手動更新-etc-resolv-conf" aria-label="Permalink to “1) 手動更新 /etc/resolv.conf”">​</a></h3><p>我們知道 <code>/etc/resolv.conf</code> （有極大的可能性）被用到，故你自然可以通過該文件增加一個 <code>nameserver</code>，那麼主機也將會（與已有的 <code>nameserver</code> 一起）使用新加入的 <code>nameserver</code> 吧？</p><p>你可以嘗試如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo nameserver 10.10.10.10 &gt;&gt; /etc/resolv.conf</span></span></code></pre></div><p>看上去新的 <code>nameserver</code> 已經加入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Dynamic resolv.conf(5) file for glibc resolver(3) generated by resolvconf(8)</span></span>
<span class="line"><span>#     DO NOT EDIT THIS FILE BY HAND -- YOUR CHANGES WILL BE OVERWRITTEN</span></span>
<span class="line"><span>nameserver 10.0.2.3</span></span>
<span class="line"><span>search home</span></span>
<span class="line"><span>nameserver 10.10.10.10</span></span></code></pre></div><p>但主機網絡服務重啓後問題出現了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl restart networking</span></span>
<span class="line"><span>$ cat /etc/resolv.conf</span></span>
<span class="line"><span># Dynamic resolv.conf(5) file for glibc resolver(3) generated by resolvconf(8)</span></span>
<span class="line"><span>#     DO NOT EDIT THIS FILE BY HAND -- YOUR CHANGES WILL BE OVERWRITTEN</span></span>
<span class="line"><span>nameserver 10.0.2.3</span></span>
<span class="line"><span>search home</span></span></code></pre></div><p>我們的 <code>10.10.10.10</code> 的 <code>nameserver</code> 不見了！</p><p>在上一篇文章中我們忽略了這一點，本文進行補充説明。</p><h3 id="_2-resolvconf" tabindex="-1">2) resolvconf <a class="header-anchor" href="#_2-resolvconf" aria-label="Permalink to “2) resolvconf”">​</a></h3><p>你在 <code>/etc/resolv.conf</code> 文件中看到 <code>generated by resolvconf</code> 詞組了吧？這就是我們的線索。</p><p>如果深入研究 <code>systemctl restart networking</code> 命令，你會發現它做了很多事情，結束時調用了 <code>/etc/network/if-up.d/000resolvconf</code> 腳本。在該腳本中，可以發現一次對 <code>resolvconf</code> 命令的調用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/sbin/resolvconf -a &quot;\${IFACE}.\${ADDRFAM}&quot;</span></span></code></pre></div><p>稍微研究一下 man 手冊，發現<code>-a</code> 參數允許我們：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Add or overwrite the record IFACE.PROG then run the update scripts</span></span>
<span class="line"><span>if updating is enabled.</span></span></code></pre></div><p>（增加或覆蓋 IFACE.PROG 記錄，如果開啓更新選項，則運行更新腳本）</p><p>故而也許我們可以直接調用該命令增加 <code>namserver</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo &#39;nameserver 10.10.10.10&#39; | /sbin/resolvconf -a enp0s8.inet</span></span></code></pre></div><p>測試表明確實可以！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /etc/resolv.conf  | grep nameserver</span></span>
<span class="line"><span>nameserver 10.0.2.3</span></span>
<span class="line"><span>nameserver 10.10.10.10</span></span></code></pre></div><p>是否已經找到答案，這就是 <code>/etc/resolv.conf</code> 更新的邏輯？調用 <code>resolvconf</code> 將 <code>nameserver</code> 添加到某個地方的資料庫，然後（“如果配置了更新”，先不管具體什麼含義）更新 <code>resolv.conf</code> 文件。</p><p>並非如此。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl restart networking</span></span>
<span class="line"><span>root@linuxdns1:/etc# cat /etc/resolv.conf </span></span>
<span class="line"><span># Dynamic resolv.conf(5) file for glibc resolver(3) generated by resolvconf(8)</span></span>
<span class="line"><span>#     DO NOT EDIT THIS FILE BY HAND -- YOUR CHANGES WILL BE OVERWRITTEN</span></span>
<span class="line"><span>nameserver 10.0.2.3</span></span>
<span class="line"><span>search home</span></span></code></pre></div><p>呃！（網絡服務重啓後）新增的 <code>nameserver</code> 再次消失了。</p><p>可見，<code>systemctl restart networking</code> 不僅僅運行了 <code>resolvconf</code>，還在其它地方獲取 <code>nameserver</code> 信息。具體是哪裏呢？</p><h3 id="_3-ifup-ifdown" tabindex="-1">3) ifup/ifdown <a class="header-anchor" href="#_3-ifup-ifdown" aria-label="Permalink to “3) ifup/ifdown”">​</a></h3><p>繼續深入研究 <code>systemctl restart networking</code>，發現它完成了一系列工作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat /lib/systemd/system/networking.service</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>[Service]</span></span>
<span class="line"><span>Type=oneshot</span></span>
<span class="line"><span>EnvironmentFile=-/etc/default/networking</span></span>
<span class="line"><span>ExecStartPre=-/bin/sh -c &#39;[ &quot;$CONFIGURE_INTERFACES&quot; != &quot;no&quot; ] &amp;&amp; [ -n &quot;$(ifquery --read-environment --list --exclude=lo)&quot; ] &amp;&amp; udevadm settle&#39;</span></span>
<span class="line"><span>ExecStart=/sbin/ifup -a --read-environment</span></span>
<span class="line"><span>ExecStop=/sbin/ifdown -a --read-environment --exclude=lo</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>首先，網絡服務的重啓實質是運行一個<ruby>單觸發<rt>oneshot</rt></ruby>的腳本，腳本包含如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/sbin/ifdown -a --read-environment --exclude=lo</span></span>
<span class="line"><span>/bin/sh -c &#39;[ &quot;$CONFIGURE_INTERFACES&quot; != &quot;no&quot; ] &amp;&amp; [ -n &quot;$(ifquery --read-environment --list --exclude=lo)&quot; ] &amp;&amp; udevadm settle&#39;</span></span>
<span class="line"><span>/sbin/ifup -a --read-environment</span></span></code></pre></div><p>第一行使用 <code>ifdown</code> 關閉全部的網絡接口，但<ruby>本地迴環<rt>local, lo</rt></ruby>接口除外。[^2]</p><p>[^2]: 我不明白為何這沒有導致我例子中的 vagrant 會話中斷 （有誰明白嗎？）。</p><p>（LCTT 譯註：其實這是因為很快就又啓動了接口，間隔的時間沒有超過 TCP 連接的超時時間，有人在評論中也做了類似回覆）</p><p>第二行用於確認系統已經完成關閉網絡接口相關的全部工作，以便下一步使用 <code>ifup</code> 啓動接口。這也讓我們瞭解到，網絡服務實質運行的就是 <code>ifdown</code> 和 <code>ifup</code>。</p><p>文檔中沒有找到 <code>--read-environment</code> 參數的説明，該參數為 <code>systemctl</code> 正常工作所需。很多人以文檔不完善為由不喜歡 <code>systemctl</code>。</p><p>很好。那麼 <code>ifup</code> （和其成對出現的 <code>ifdown</code>） 到底做了哪些工作呢？長話短説，它運行了 <code>/etc/network/if-pre-up.d/</code> 和 <code>/etc/network/if-up.d/</code> 目錄下的全部腳本；期間，這些腳本也可能會調用另外的腳本，依此類推。</p><p>其中一件工作就是運行了 <code>dhclient</code>，但我還不完全確定具體的機理，也許 <code>udev</code> 參與其中。</p><h3 id="_4-dhclient" tabindex="-1">4) dhclient <a class="header-anchor" href="#_4-dhclient" aria-label="Permalink to “4) dhclient”">​</a></h3><p><code>dhclient</code> 是一個程序，用於與 DHCP 服務器協商對應網絡接口應該使用的 IP 地址的詳細信息。同時，它也可以獲取可用的 DNS 服務器並將其替換到 <code>/etc/resolv.conf</code> 中。</p><p>讓我們開始跟蹤並模擬它的行為，但僅在我實驗虛擬機的 <code>enp0s3</code> 接口上。事先已經刪除 <code>/etc/resolv.conf</code> 文件中的 nameserver 配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sed -i &#39;/nameserver.*/d&#39; /run/resolvconf/resolv.conf</span></span>
<span class="line"><span>$ cat /etc/resolv.conf | grep nameserver</span></span>
<span class="line"><span>$ dhclient -r enp0s3 &amp;&amp; dhclient -v enp0s3</span></span>
<span class="line"><span>Killed old client process</span></span>
<span class="line"><span>Internet Systems Consortium DHCP Client 4.3.3</span></span>
<span class="line"><span>Copyright 2004-2015 Internet Systems Consortium.</span></span>
<span class="line"><span>All rights reserved.</span></span>
<span class="line"><span>For info, please visit https://www.isc.org/software/dhcp/</span></span>
<span class="line"><span>Listening on LPF/enp0s8/08:00:27:1c:85:19</span></span>
<span class="line"><span>Sending on   LPF/enp0s8/08:00:27:1c:85:19</span></span>
<span class="line"><span>Sending on   Socket/fallback</span></span>
<span class="line"><span>DHCPDISCOVER on enp0s8 to 255.255.255.255 port 67 interval 3 (xid=0xf2f2513e)</span></span>
<span class="line"><span>DHCPREQUEST of 172.28.128.3 on enp0s8 to 255.255.255.255 port 67 (xid=0x3e51f2f2)</span></span>
<span class="line"><span>DHCPOFFER of 172.28.128.3 from 172.28.128.2</span></span>
<span class="line"><span>DHCPACK of 172.28.128.3 from 172.28.128.2</span></span>
<span class="line"><span>bound to 172.28.128.3 -- renewal in 519 seconds.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ cat /etc/resolv.conf | grep nameserver</span></span>
<span class="line"><span>nameserver 10.0.2.3</span></span></code></pre></div><p>可見這就是 <code>nameserver</code> 的來源。</p><p>但稍等一下，命令中的 <code>/run/resolvconf/resolv.conf</code> 是哪個文件，不應該是 <code>/etc/resolv.conf</code> 嗎？</p><p>事實上，<code>/etc/resolv.conf</code> 並不一定只是一個普通文本文件。</p><p>在我的虛擬機上，它是一個軟鏈接，指向位於 <code>/run/resolvconf</code> 目錄下的“真實文件”。這也暗示了我們，該文件是在系統啓動時生成的；同時，這也是該文件註釋告訴我們不要直接修改該文件的原因。</p><p>（LCTT 譯註：在 CentOS 7 中，沒有 <code>resolvconf</code> 命令，<code>/etc/resolv.conf</code> 也不是軟鏈接）</p><p>假如上面命令中 <code>sed</code> 命令直接處理 <code>/etc/resolv.conf</code> 文件，效果是不同的，會有警告消息告知待操作的文件不能是軟鏈接（<code>sed -i</code> 無法很好的處理軟鏈接，它只會創建一個新文件）。</p><p>（LCTT 譯註：CentOS 7 測試時，<code>sed -i</code> 命令操作軟鏈接並沒有警告，但確實創建了新文件取代軟鏈接）</p><p>如果你繼續深入查看配置文件 <code>/etc/dhcp/dhclient.conf</code> 的 <code>supersede</code> 部分，你會發現 <code>dhclient</code> 可以覆蓋 DHCP 提供的 DNS 服務器。</p><p><img src="https://zwischenzugs.files.wordpress.com/2018/06/linux-dns-2-2.png?w=525" alt="linux-dns-2 (2)"></p><p><em>（大致）準確的關係圖</em></p><hr><h3 id="第二部分的結束語" tabindex="-1">第二部分的結束語 <a class="header-anchor" href="#第二部分的結束語" aria-label="Permalink to “第二部分的結束語”">​</a></h3><p>第二部分到此結束。信不信由你，這是一個某種程度上簡化的流程版本，但我儘量保留重要和值得了解的部分，讓你不會感到無趣。大部分內容都是圍繞實際腳本的運行展開的。</p><p>但我們的工作還沒有結束，在第三部分，我們會介紹這些之上的更多層次。</p><p>讓我們簡要列出我們已經介紹過的內容：</p><ul><li><code>nsswitch</code></li><li><code>/etc/hosts</code></li><li><code>/etc/resolv.conf</code></li><li><code>/run/resolvconf/resolv.conf</code></li><li><code>systemd</code> 和網絡服務</li><li><code>ifup</code> 和 <code>ifdown</code></li><li><code>dhclient</code></li><li><code>resolvconf</code></li></ul><hr>`,61)),o("p",null,[e[7]||(e[7]=s("via: ",-1)),a(n,{href:"https://zwischenzugs.com/2018/06/18/anatomy-of-a-linux-dns-lookup-part-ii/"},{default:i(()=>[...e[6]||(e[6]=[s("https://zwischenzugs.com/2018/06/18/anatomy-of-a-linux-dns-lookup-part-ii/",-1)])]),_:1})]),o("p",null,[e[11]||(e[11]=s("作者：",-1)),a(n,{href:"https://zwischenzugs.com/"},{default:i(()=>[...e[8]||(e[8]=[s("ZWISCHENZUGS",-1)])]),_:1}),e[12]||(e[12]=s(" 譯者：",-1)),a(n,{href:"https://github.com/pinewall"},{default:i(()=>[...e[9]||(e[9]=[s("pinewall",-1)])]),_:1}),e[13]||(e[13]=s(" 校對：",-1)),a(n,{href:"https://github.com/wxy"},{default:i(()=>[...e[10]||(e[10]=[s("wxy",-1)])]),_:1})]),o("p",null,[e[16]||(e[16]=s("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[14]||(e[14]=[s("LCTT",-1)])]),_:1}),e[17]||(e[17]=s(" 原創編譯，",-1)),a(n,{href:"https://linux.cn/"},{default:i(()=>[...e[15]||(e[15]=[s("Linux中國",-1)])]),_:1}),e[18]||(e[18]=s(" 榮譽推出",-1))])])}const y=t(r,[["render",h]]);export{C as __pageData,y as default};
